  },
  {
    "question": "What potential solution have AI researchers from Microsoft, OpenAI, and universities suggested to overcome online deception enabled by AI models?",
    "answer": "They have suggested using \"personhood credentials\" as a way to overcome online deception enabled by AI models.",
    "estimated_difficulty": 5,
    "citations": ["AI researchers at Microsoft, OpenAI, universities and other organisations have suggested using \"personhood credentials\" as a way to overcome online deception enabled by AI models."]
  },
  {
    "question": "According to the text, what are the two main ways bias can be introduced into a machine learning model?",
    "answer": "Bias can be introduced by the way training data is selected and by the way a model is deployed.",
    "estimated_difficulty": 4,
    "citations": ["Bias can be introduced by the way training data is selected and by the way a model is deployed."]
  },
  {
    "question": "What was the status of Google Photos's ability to identify a gorilla in 2023, eight years after the initial labeling error?",
    "answer": "Eight years later, in 2023, Google Photos still could not identify a gorilla, and neither could similar products from Apple, Facebook, Microsoft and Amazon.",
    "estimated_difficulty": 3,
    "citations": ["Eight years later, in 2023, Google Photos still could not identify a gorilla, and neither could similar products from Apple, Facebook, Microsoft and Amazon."]
  }
]

